// The day's affirmation in Finnish, for the country pages in Finnish. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Sinun ei tarvitse tehdä kaikkea tänään. Seuraava pieni asia riittää.\", \"Väsymys ei ole epäonnistumista. Olet väsynyt, koska olet paikalla päivästä toiseen.\", \"Tiskit voivat odottaa. Saat istahtaa viideksi minuutiksi.\", \"Murot iltaruoaksi ovat nekin perheen ruokkimista.\", \"Lepoa ei tarvitse ansaita. Saat levätä juuri nyt.\", \"Joskus voitto on se, että kaikki selvisivät nukkumaanmenoon asti. Se on oikea voitto.\", \"Teet enemmän kuin kukaan näkee. Minä näen sen.\", \"Sotkuinen koti ja rakastetut lapset. Hyvä vaihtokauppa.\", \"Raskaana päivänä sinun parhaasi näyttää erilaiselta, ja sekin on arvokasta.\", \"Yksi syvä hengenveto. Laske hartiat. Pärjäät hyvin.\", \"Tänään saa laskea rimaa. Voit nostaa sen taas toisena päivänä.\", \"Avun pyytäminen on vahvuutta, ei heikkoutta.\", \"Saat sanoa ei vielä yhdelle asialle.\", \"Jos tunsit itsesi tänään yksinäiseksi, et ole ainoa äiti, joka on tuntenut niin. Meitä on paljon.\", \"Ansaitset ystävän, joka kysyy, mitä sinulle kuuluu, ja jää kuuntelemaan vastauksen.\", \"On ihan ok ottaa itse ensin yhteyttä. Useimmat äidit toivovat, että joku tekisi niin.\", \"Vaikka tuntisit itsesi näkymättömäksi, olet tärkeä. Todella tärkeä.\", \"Tunteesi ovat ymmärrettäviä. Et ole liikaa.\", \"Täällä sinun ei tarvitse selittää raskasta päivääsi. Me ymmärrämme.\", \"Viesti toiselle äidille, jossa lukee ”niin minäkin”, voi kääntää koko päivän.\", \"Syöttämistä, vaipanvaihtoa, tuudittamista ja taas alusta. Se on oikeaa työtä, vaikka näyttäisi paikallaan istumiselta.\", \"Sinä ja vauvasi tutustutte vielä toisiinne. Ei ole mikään kiire.\", \"Päivät vastasyntyneen kanssa ovat pitkiä. Tämä vaihe ei kestä ikuisesti.\", \"Jos ainoa asia, jonka tänään teit, oli pitää pieni ihminen kylläisenä ja lämpimänä, teit ison työn.\", \"Sinun ei tarvitse palautua nopeasti ennalleen. Saat olla juuri siinä, missä olet.\", \"Miten tahansa vauvasi saakin ruokansa, sinä huolehdit vauvastasi. Se on tärkeintä.\", \"Voit olla univelkainen ja täynnä rakkautta yhtä aikaa.\", \"Pidä vauvaa sylissä ja anna kodin olla. Koti on vielä huomennakin siinä.\", \"Kiukkukohtaus kaupassa ei tee sinusta huonoa äitiä. Se tarkoittaa vain, että sinulla on taapero.\", \"Pienet koettelevat rajoja, koska tuntevat olonsa turvalliseksi kanssasi.\", \"Pysyit tänään rauhallisena minuutin pidempään kuin eilen. Sekin on tärkeää.\", \"Jos menetit malttisi, halaus ja ”anteeksi” korjaavat paljon. Ja se opettaa heille jotain hyvää.\", \"Tahmeat kädet, kovat äänet, isot tunteet. Kasvatat kokonaista ihmistä.\", \"Tunnin viides ”miksi?” on pieni mieli kasvamassa.\", \"Onnelliseen muistoon ei tarvita täydellistä päivää.\", \"Paiskattu ovi ei ole tarinan loppu. Jätä valo palamaan.\", \"Teinisi ei ehkä sano sitä, mutta sillä on merkitystä, että olet aina siinä.\", \"On raskasta olla kodin rauhallinen ihminen. Ja sinä olet.\", \"Jotkut parhaista keskusteluista käydään autossa. Aja vain eteenpäin.\", \"He ottavat etäisyyttä kasvaakseen, eivät jättääkseen sinut.\", \"Sinun ei tarvitse tietää kaikkia vastauksia. Kuunteleminen on iso osa sitä.\", \"Isommatkin lapset tarvitsevat sinua, vain hiljaisemmin.\", \"Yksin pärjääminen vaatii voimaa, jota useimmat eivät koskaan näe.\", \"Olet tarpeeksi hyvä äiti lapsellesi. Olet aina ollut.\", \"Yhdet kädet, sata tehtävää. Ole itsellesi lempeä.\", \"Lapsesi oppivat sinua katsomalla, millainen on vahva ja rakastava ihminen.\", \"Tauko ei ole paikaltaan karkaamista. Sen avulla jaksat.\", \"Kukaan ei pidä pistekirjanpitoa. Rakkaus ja läsnäolo ovat tärkeimpiä.\", \"Suru ja rakkaus tulevat samasta paikasta. Ikävä kertoo, kuinka paljon olet rakastanut.\", \"Surulle ei ole oikeaa aikataulua. Ota se aika, jonka tarvitset.\", \"Vaikeina vuosipäivinä ole itsellesi yhtä lempeä kuin olisit ystävällesi.\", \"Voit kantaa surua ja silti nauraa lastesi kanssa. Molemmat ovat totta.\", \"Jos menetit raskauden tai vauvan, menetys on todellinen, ja niin on rakkautesikin.\", \"Joskus suru on hiljaista ja joskus äänekästä. Molemmat ovat ok.\", \"Vähät rahat eivät tarkoita vähää rakkautta.\", \"Lapsesi muistavat kanssasi vietetyn ajan paremmin kuin tavarat, joita ostit.\", \"Avun kysyminen laskuihin on fiksua, ei häpeällistä. Juuri sitä varten apu on olemassa.\", \"Ilmainen iltapäivä puistossa voi olla viikon paras päivä.\", \"Sait rahat riittämään vielä viikon. Siihen tarvitaan todellista taitoa.\", \"Rahahuolet väsyttävät. Kannat paljon, ja olet silti yhä tässä.\", \"Joit tänään lasillisen vettä. Aloita siitä.\", \"Kaikki pääsivät ovesta ulos. Kengät eivät ehkä olleet pari. Silti voitto.\", \"Soitit sen puhelun, jota jännitit. Se oli rohkeaa.\", \"Nauroit tänään. Pidä siitä kiinni.\", \"Lämmin ateria, puhdas paita, iltasatu. Pienistä asioista koostuu lapsuus.\", \"Olit tänään ystävällinen jollekulle, vaikka vain itsellesi.\", \"Edistystä, ei täydellisyyttä. Pääsit tänään eteenpäin.\", \"Sait yhden asian listalta tehdyksi. Se on yksi enemmän kuin ei yhtään.\", \"Olet hyvä äiti. Se, että murehdit sitä, kertoo kuinka paljon välität.\", \"Olet enemmän kuin se, mitä saat päivässä aikaan.\", \"Lapsesi eivät tarvitse täydellistä äitiä. He tarvitsevat sinua, ja sinä olet heillä.\", \"Ole itsellesi yhtä kärsivällinen kuin lapsillesi.\", \"Saat viedä tilaa, haluta asioita ja unelmoida omia unelmiasi.\", \"Virhe ei pyyhi rakkautta pois. Huominen on uusi alku.\", \"Olet jollekulle koko maailma, ja olet myös oma itsesi.\", \"On ok, ettei jokainen hetki ole ihana. Voit silti rakastaa lapsiasi koko sydämestäsi.\", \"Ei ole yhtä oikeaa tapaa olla äiti. Sinun tapasi on yhtä hyvä.\", \"Kuten puuasennossa, saa huojua. Löydät tasapainosi uudelleen.\", \"Asetu tukevasti kuin vuoriasennossa. Seisot vakaammin kuin miltä tuntuu.\", \"Soturi kaksi: vahvat jalat, avoimet kädet. Siinä olet sinä tämän viikon edessä.\", \"Hengitä sisään neljään, ulos neljään. Olet tässä, ja pärjäät hyvin.\", \"Venyttäydy leveäksi kuin tähti. Saat viedä tilaa.\", \"Leveässä, matalassa kyykyssä on vaikea pysyä. Niin on pitkässä päivässäkin. Ja sinä pysyt.\", \"Voit kallistua kuin kuunsirppi ja pysyä silti pystyssä.\", \"Sinun ei tarvitse vielä ylettyä varpaisiin. Jokainen pieni venytys on tärkeä.\", \"Kolmioasento: toinen käsi alas, toinen ylös. Pysy maadoittuneena ja kurota yhä.\", \"On myöhä. Mikä jäi tänään tekemättä, voi odottaa huomiseen.\", \"Hereillä vauvan kanssa tähän aikaan? Moni äiti valvoo kanssasi juuri nyt.\", \"Talo on hiljainen. Tämä hetki on sinun. Hengitä.\", \"Selvisit tästä päivästä. Muuta päivä ei tarvinnut.\", \"Jos ajatukset pyörivät tänä yönä, kirjoita ne ylös ja anna niiden odottaa aamuun.\", \"Lepuuta silmiäsi. Huomenna saat aloittaa alusta.\", \"Juhlapyhät voivat olla raskaita yhtä lailla kuin iloisia. Miltä tämä aika sinusta tuntuukin, se on ok.\", \"Pöydän ei tarvitse olla täydellinen. Sen ympärillä olevat ihmiset ovat tärkeimpiä.\", \"Jos joku puuttuu tänä vuonna pöydän äärestä, ole hellä sydämellesi.\", \"Kiitos, äiti, jokaisesta ateriasta, jokaisesta kyydistä ja jokaisesta halauksesta.\", \"Sinun ei tarvitse kestitä, leipoa tai hymyillä koko ajan. Yksinkertainen juhla on silti juhla.\", \"Paras lahja, jonka lapsesi tänä vuonna saavat, on aika kanssasi.\", \"Pieni joulu on silti täynnä rakkautta. Ei tarvita paljon rahaa, jotta siitä tulee erityinen.\", \"Kylmät päivät, lämpimät halaukset. Sinä olet kotisi lämmin paikka.\", \"On ok jättää osa joulukiireestä väliin. Rauhakin on lahja.\", \"Jos juhla-aika tuntuu tänä vuonna raskaalta, et ole yksin. Päivä kerrallaan.\"]";D.body.appendChild(e)})();
